    { id = "item:16327:description", html = false,
      ja = "Imp Fire Shield（Rank $N1）を習得します。",
      out = "インプ・ファイア・シールド（ランク $N1）を習得します。" },
    { id = "item:17193:description", html = false,
      ja = "火の玉を投げつけて$N1のFireダメージを与え、さらに$D1かけて$N2のダメージを追加で与えます。",
      out = "火の玉を投げつけて$N1のファイアダメージを与え、さらに$D1かけて$N2のダメージを追加で与えます。" },
    { id = "item:18406:description", html = false,
      ja = "$D1の間、Dragon Breath呪文から受ける魔法ダメージを$N1%軽減します。",
      out = "$D1の間、ドラゴン・ブレス呪文から受ける魔法ダメージを$N1%軽減します。" },
    { id = "item:18851:description", html = false,
      ja = "Fear、Polymorph、Stunの効果をすべて解除します。",
      out = "フィアー、ポリモーフ、スタンの効果をすべて解除します。" },
    { id = "item:19289:description", html = false,
      ja = "一定の確率で近接攻撃の対象に稲妻を落とし、$N1のNatureダメージを与えます。Aquaticの敵には$N2倍のダメージを与えます。",
      out = "一定の確率で近接攻撃の対象に稲妻を落とし、$N1のネイチャーダメージを与えます。アクアティックの敵には$N2倍のダメージを与えます。" },
    { id = "item:19991:description", html = false,
      ja = "【使用】$D1以内の次の近接攻撃または遠隔攻撃が、対象を$D2の間Rootする。対象が移動していた場合、この効果の持続時間は倍になる。Beastsにのみ有効。",
      out = "【使用】$D1以内の次の近接攻撃または遠隔攻撃が、対象を$D2の間ルートする。対象が移動していた場合、この効果の持続時間は倍になる。ビーストにのみ有効。" },
    { id = "item:204716:description", html = false,
      ja = "新しいEngravingのアビリティを習得します。",
      out = "新しいエングレイビングのアビリティを習得します。" },
    { id = "item:208414:description", html = false,
      ja = "Moonfireの影響を受けている敵を$N1体倒したあと、これを使って新しいアビリティを習得します。",
      out = "ムーンファイアの影響を受けている敵を$N1体倒したあと、これを使って新しいアビリティを習得します。" },
    { id = "item:211472:description", html = false,
      ja = "$N1体の敵にTurn Undeadをかけ、Exorcismで倒したあと、新しいアビリティを習得します。",
      out = "$N1体の敵にターン・アンデッドをかけ、エクソシズムで倒したあと、新しいアビリティを習得します。" },
    { id = "item:213118:description", html = false,
      ja = "新しいEngravingのアビリティを習得します。",
      out = "新しいエングレイビングのアビリティを習得します。" },
    { id = "item:2154:description", html = false,
      ja = "[Morgan Ladimoreの物語]\n右クリックで読む。",
      out = "[モーガン・ラディモアの物語]\n右クリックで読む。" },
    { id = "item:220013:description", html = false,
      ja = "このメッセージは、受け取ると自動的に消滅する。Field Captainはあなたの行動について一切関知しない。",
      out = "このメッセージは、受け取ると自動的に消滅する。フィールド・キャプテンはあなたの行動について一切関知しない。" },
    { id = "item:221290:description", html = false,
      ja = "DunesのAceからEightまでを組み合わせて、セットを完成させます。",
      out = "デューンのエースからエイトまでを組み合わせて、セットを完成させます。" },
    { id = "item:22396:description", html = false,
      ja = "Lesser Healing Waveの回復量を最大$N1増加させます。",
      out = "レッサー・ヒーリング・ウェーブの回復量を最大$N1増加させます。" },
    { id = "item:227041:description", html = false,
      ja = "この装置は忌まわしい死の力を導いて向け、肉でも金属でも、ありふれたものでも魔法のものでも、あらゆる物質を溶かします。Arkonosを守る障壁を乱せるかもしれません。",
      out = "この装置は忌まわしい死の力を導いて向け、肉でも金属でも、ありふれたものでも魔法のものでも、あらゆる物質を溶かします。アーコノスを守る障壁を乱せるかもしれません。" },
    { id = "item:227905:description", html = false,
      ja = "Masterwork Stormhammerの作り方を習得します。",
      out = "マスターワーク・ストームハンマーの作り方を習得します。" },
    { id = "item:231800:description", html = false,
      ja = "ソウルシャードをDepleted Scythe of Chaosと組み合わせます。",
      out = "ソウルシャードをディプリーテッド・サイズ・オブ・カオスと組み合わせます。" },
    { id = "item:235790:description", html = false,
      ja = "Enchanted Torchを掲げ、Karazhan Crypts付近の闇を払おうと試みます。",
      out = "エンチャンテッド・トーチを掲げ、カラザン・クリプト付近の闇を払おうと試みます。" },
    { id = "item:240061:description", html = false,
      ja = "攻撃が回避または受け流される確率を$N1%低下させます。\nWeapon Damageが$N2上昇します。",
      out = "攻撃が回避または受け流される確率を$N1%低下させます。\nウェポン・ダメージが$N2上昇します。" },
    { id = "item:249866:description", html = false,
      ja = "$D1かけてマナを$N1回復します。飲んでいる間は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間Healing Powerが$N4上昇します。$?pc142418[さらに、敵を倒して得られる経験値が$N6%増加します。][]",
      out = "$D1かけてマナを$N1回復します。飲んでいる間は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間ヒーリング・パワーが$N4上昇します。$?pc142418[さらに、敵を倒して得られる経験値が$N6%増加します。][]" },
    { id = "item:251367:description", html = false,
      ja = "Protector's Chain Beltの作り方を習得します。",
      out = "プロテクターズ・チェーン・ベルトの作り方を習得します。" },
    { id = "item:252761:description", html = false,
