    { id = "item:254090:description", html = false,
      ja = "Golden Waistcordの作り方を習得します。",
      out = "ゴールデン・ウエストコードの作り方を習得します。" },
    { id = "item:264216:description", html = false,
      ja = "Emergency Field Cloakの作り方を習得します。",
      out = "エマージェンシー・フィールド・クロークの作り方を習得します。" },
    { id = "item:272432:description", html = false,
      ja = "Lightning BoltでもMaelstrom Weaponのタレントが発動するようになりますが、確率は$N1%低下します。",
      out = "ライトニング・ボルトでもメイルストロム・ウェポンのタレントが発動するようになりますが、確率は$N1%低下します。" },
    { id = "item:273841:description", html = false,
      ja = "対象に$N1のNatureダメージを与えます。",
      out = "対象に$N1のネイチャーダメージを与えます。" },
    { id = "item:275239:description", html = false,
      ja = "高位の古参兵がHandの防具を強化するのに使います。",
      out = "高位の古参兵がハンドの防具を強化するのに使います。" },
    { id = "item:277491:description", html = false,
      ja = "$D1の間、対象のElementalがあなたの呪文から受けるダメージを$N1%増加させます。レベル$N3以下の敵にのみ効果があります。",
      out = "$D1の間、対象のエレメンタルがあなたの呪文から受けるダメージを$N1%増加させます。レベル$N3以下の敵にのみ効果があります。" },
    { id = "item:281042:description", html = false,
      ja = "Bundle of Herbs、Bundle of Dried Cedar Twigs、Sinew Thread、Ceremonial Flint and Tinderを組み合わせてPrepared Incenseを作ります。",
      out = "バンドル・オブ・ハーブ、バンドル・オブ・ドライド・シーダー・トゥイッグ、シニュー・スレッド、セレモニアル・フリント・アンド・ティンダーを組み合わせてプリペアド・インセンスを作ります。" },
    { id = "item:3091:description", html = false,
      ja = "Arcane Intellect（Rank $N1）を習得します。",
      out = "アーケイン・インテレクト（ランク $N1）を習得します。" },
    { id = "item:4198:description", html = false,
      ja = "Health Funnel（Rank $N1）を習得します。",
      out = "ヘルス・ファンネル（ランク $N1）を習得します。" },
    { id = "item:5028:description", html = false,
      ja = "聖なる泉の力で対象を打ち据え、$N1のHolyダメージを与えます。\n聖なる泉の力が王笏から放たれています。",
      out = "聖なる泉の力で対象を打ち据え、$N1のホーリーダメージを与えます。\n聖なる泉の力が王笏から放たれています。" },
    { id = "item:5788:description", html = false,
      ja = "Thick Murloc Armorの製作方法を習得します。",
