    { id = "item:8896:description", html = false,
      ja = "Blizzard（Rank $N1）を習得します。",
      out = "ブリザード（ランク $N1）を習得します。" },
    { id = "item:9068:description", html = false,
      ja = "Lightning Shield（Rank $N1）を習得します。",
      out = "ライトニング・シールド（ランク $N1）を習得します。" },
    { id = "item:9294:description", html = false,
      ja = "Wildvine Potionの作り方を習得する。",
      out = "ワイルドヴァイン・ポーションの作り方を習得する。" },
    { id = "objective:382533:text", html = false,
      ja = "Highvale Reportを焼き払う",
      out = "ハイヴェイル・レポートを焼き払う" },
    { id = "objective:465190:text", html = false,
      ja = "Thendal Groveのレイラインの近くで能力Read Leylineを使う",
      out = "センダル・グローヴのレイラインの近くで能力リード・レイラインを使う" },
    { id = "objective:475002:text", html = false,
      ja = "Warsong Gulchの戦場を3回完了する",
      out = "ウォーソング・ガルチの戦場を3回完了する" },
    { id = "quest:1000:objectives", html = false,
      ja = "Cenarion CircleによるKalimdor辺境地域探索の呼びかけについて、Thunder BluffのElder RiseにいるArch Druid Hamuul Runetotemと話して下さい。",
      out = "セナリウス・サークルによるカリムドア辺境地域探索の呼びかけについて、サンダー・ブラフのエルダー・ライズにいるアーチ・ドルイド・ハムール・ルーントーテムと話して下さい。" },
    { id = "quest:1034:progress", html = false,
      ja = "Stardustはもう手に入れましたか、{name}?",
      out = "スターダストはもう手に入れましたか、{name}?" },
    { id = "quest:1068:completion", html = false,
      ja = "XT:4とXT:9という機械が破壊されたことで、Stonetalonの多くの精霊が慰められました、{name}。それらを失ったことで、Venture Companyがこの山々から立ち去ってくれることを願いましょう。\n\nもしそうならなければ、この地がこれまで受けてきた残虐も、これから待ち受けるものに比べれば色あせてしまうのではないかと恐れています。",
      out = "エックスティー:4とエックスティー:9という機械が破壊されたことで、ストーンタロンの多くの精霊が慰められました、{name}。それらを失ったことで、ベンチャー・カンパニーがこの山々から立ち去ってくれることを願いましょう。\n\nもしそうならなければ、この地がこれまで受けてきた残虐も、これから待ち受けるものに比べれば色あせてしまうのではないかと恐れています。" },
    { id = "quest:1104:progress", html = false,
      ja = "やあやあやあ! あのvenom、手に入れた??",
      out = "やあやあやあ! あのヴェノム、手に入れた??" },
    { id = "quest:113:progress", html = false,
      ja = "さて、Junior Surveyor {name}、Pestlezuggの奴は報告書をもう用意できたか？",
      out = "さて、ジュニア・サーベイヤー {name}、ペストルズグの奴は報告書をもう用意できたか？" },
    { id = "quest:1187:title", html = false,
      ja = "Razzericの調整",
      out = "ラゼリックの調整" },
    { id = "quest:1247:description", html = false,
      ja = "で、まあ……その……Addle's Steadでの集まりについて、ちょいと知ってるかもしれねえ。二、三週間前だったと思う。俺はほとんど関わってねえんだ。A計画がしくじった時点で俺の役目は終わりだった……くそったれの冒険者どもめ。\n\nB計画のために送り込んだ内通者はMenethilから来た奴だ。Slimって呼ばれてる。奴らの予備の計画について知ってるのはそれだけだ。",
      out = "で、まあ……その……アドルズ・ステッドでの集まりについて、ちょいと知ってるかもしれねえ。二、三週間前だったと思う。俺はほとんど関わってねえんだ。A計画がしくじった時点で俺の役目は終わりだった……くそったれの冒険者どもめ。\n\nB計画のために送り込んだ内通者はメネシルから来た奴だ。スリムって呼ばれてる。奴らの予備の計画について知ってるのはそれだけだ。" },
    { id = "quest:1319:objectives", html = false,
      ja = "Blackened Iron ShieldをTheramoreのCaz Twosprocketに見せて下さい。",
      out = "ブラックンド・アイアン・シールドをセラモアのカズ・トゥースプロケットに見せて下さい。" },
    { id = "quest:1384:progress", html = false,
      ja = "charmsを持ってきたか？Kolkarに奴らが弱いと思い知らせたか？",
      out = "チャームを持ってきたか？コルカーに奴らが弱いと思い知らせたか？" },
    { id = "quest:1439:title", html = false,
      ja = "Tyranisの捜索",
      out = "ティラニスの捜索" },
    { id = "quest:1476:description", html = false,
      ja = "succubusをおびき寄せるには、清らかな者の心臓が要る。だが、悪徳を持たぬ定命の者などいるだろうか?\n\n漏れ聞いた話の断片から、うってつけの人間を2人見つけた。\n\n一人目はDalin Forgewright。Greymane Wallで同族に拒まれたLordaeronの避難民の世話に身を捧げている男だ。\n\nもう一人はCorma Villard。失った恋人に今も操を立て、その手がかりを求めてWetlandsをさまよっている女だ。\n\n二人の心臓をCarendinに届けろ。だがまずは、お前の獲物を見せてやろう。",
      out = "サキュバスをおびき寄せるには、清らかな者の心臓が要る。だが、悪徳を持たぬ定命の者などいるだろうか?\n\n漏れ聞いた話の断片から、うってつけの人間を2人見つけた。\n\n一人目はダリン・フォージライト。グレイメイン・ウォールで同族に拒まれたローデロンの避難民の世話に身を捧げている男だ。\n\nもう一人はコーマ・ヴィラード。失った恋人に今も操を立て、その手がかりを求めてウェットランドをさまよっている女だ。\n\n二人の心臓をカレンディンに届けろ。だがまずは、お前の獲物を見せてやろう。" },
    { id = "quest:1515:objectives", html = false,
      ja = "BarrensのDogranにKen'zigla's Draughtを渡して下さい。",
      out = "バレンズのドグランにケンジグラズ・ドラフトを渡して下さい。" },
    { id = "quest:1638:description", html = false,
      ja = "君は有能なウォリアーであることを示した、{name}。だが、まだ若く、学ぶことはたくさんある。\n\nHarry Burlguardと話してみろ――たいていはStormwindのOld TownにあるPig and Whistleという酒場にいる。Harryは古参の兵で、良い教師だ。長生きできる技をいくつか教えてくれるだろう。",
      out = "君は有能なウォリアーであることを示した、{name}。だが、まだ若く、学ぶことはたくさんある。\n\nハリー・バールガードと話してみろ――たいていはストームウィンドのオールド・タウンにあるピッグ・アンド・ホイッスルという酒場にいる。ハリーは古参の兵で、良い教師だ。長生きできる技をいくつか教えてくれるだろう。" },
    { id = "quest:1688:completion", html = false,
      ja = "Surenaには才能があったが、独力でウォーロックの魔法を極めるには足りなかった。才能が無駄になるのは惜しいが、時には必要なことだ。\n\nお前への投資は違う結果を生むことを期待している。",
      out = "スリーナには才能があったが、独力でウォーロックの魔法を極めるには足りなかった。才能が無駄になるのは惜しいが、時には必要なことだ。\n\nお前への投資は違う結果を生むことを期待している。" },
    { id = "quest:176:progress", html = false,
      ja = "ああ、Hoggerには私も部下もずいぶん手を焼いている。あの獣について何か報告があるのか？",
      out = "ああ、ホガーには私も部下もずいぶん手を焼いている。あの獣について何か報告があるのか？" },
    { id = "quest:182:description", html = false,
      ja = "私と兄弟のSenirは、トロールがもたらす脅威を調べるために、Dun Moroghの別々の場所へ送られた。Senateはtroggsの相手で手一杯だから、これ以上の厄介事は要らないというわけだ。\n\n見たところ、トロールどもはここColdridge Valleyにはたいした陣地を築いていない――ほとんどは南の洞窟にいる。軍を出すまでもないだろう。腕っぷしの強い者が何人かいれば十分すぎるほどだ。\n\nこの仕事を手伝ってみる気はないか？ 手を貸してくれるなら、報酬を出す権限が私にはある。",
      out = "私と兄弟のセニアは、トロールがもたらす脅威を調べるために、ダン・モローの別々の場所へ送られた。セネトはトログの相手で手一杯だから、これ以上の厄介事は要らないというわけだ。\n\n見たところ、トロールどもはここコールドリッジ・バレーにはたいした陣地を築いていない――ほとんどは南の洞窟にいる。軍を出すまでもないだろう。腕っぷしの強い者が何人かいれば十分すぎるほどだ。\n\nこの仕事を手伝ってみる気はないか？ 手を貸してくれるなら、報酬を出す権限が私にはある。" },
    { id = "quest:193:progress", html = false,
      ja = "Bhag'theraはなかなか捕まらない獣かもしれん。狩りの首尾はどうだ？",
      out = "バグセラはなかなか捕まらない獣かもしれん。狩りの首尾はどうだ？" },
    { id = "quest:205:description", html = false,
      ja = "君が手に入れた伝承を私が研究している間に、邪悪なトロールの魔術の道具を集めてきてくれ。はるか南にいる第二の部族、Skullsplitterトロールの縄張りに入り、そのWitchdoctorsとMysticsからSkullsplitter Fetishesを手に入れるのだ。",
      out = "君が手に入れた伝承を私が研究している間に、邪悪なトロールの魔術の道具を集めてきてくれ。はるか南にいる第二の部族、スカルスプリッタートロールの縄張りに入り、そのウィッチドクターとミスティックからスカルスプリッター・フェティッシュを手に入れるのだ。" },
    { id = "quest:2238:objectives", html = false,
      ja = "Gnomeregan付近にいるOnin MacHammarを探して下さい。",
      out = "ノームリガン付近にいるオニン・マクハマーを探して下さい。" },
    { id = "quest:2378:completion", html = false,
      ja = "それで、我らの強力な同盟者がShenthulに寄越してきたのが、お前か? なんてパッとしない……",
      out = "それで、我らの強力な同盟者がシェンサルに寄越してきたのが、お前か? なんてパッとしない……" },
    { id = "quest:2523:completion", html = false,
      ja = "songflower に Cenarion 植物用軟膏 (plant salve) を塗った。植物は即座に元の姿を取り戻し始め、色鮮やかな瑞々しい植物が現れた。",
      out = "ソングフラワー に セナリウス 植物用軟膏 (プラント・サルブ) を塗った。植物は即座に元の姿を取り戻し始め、色鮮やかな瑞々しい植物が現れた。" },
    { id = "quest:271:title", html = false,
      ja = "Vyrinの復讐",
      out = "ヴァイリンの復讐" },
    { id = "quest:2783:description", html = false,
      ja = "我々は戦う相手を間違えている、{name}。\n\nこの地の真の力は、我々がオークどもと焦土を奪い合っている間にも、力と数を増し続けている。\n\nこの地でHordeを相手に戦を続け、いつの日かBurning Legionの軍勢に蹴散らされるだけなのか？ 無益なことだ。\n\n互いの違いはひとまず脇に置け、{name}。Hordeの倒れた英雄と話すのだ。彼はBlasted Landsの背後にある真実を知っている。",
      out = "我々は戦う相手を間違えている、{name}。\n\nこの地の真の力は、我々がオークどもと焦土を奪い合っている間にも、力と数を増し続けている。\n\nこの地でホードを相手に戦を続け、いつの日かバーニング・レギオンの軍勢に蹴散らされるだけなのか？ 無益なことだ。\n\n互いの違いはひとまず脇に置け、{name}。ホードの倒れた英雄と話すのだ。彼はブラステッド・ランドの背後にある真実を知っている。" },
    { id = "quest:2867:description", html = false,
      ja = "Ruins of Solarsalの中心で奇妙なあずまやが見つかった今、Feathermoon Strongholdへ戻り、ここで見つかったことをGeneral Shandris Feathermoonに報告する時が来た。",
      out = "ルイン・オブ・ソラーサルの中心で奇妙なあずまやが見つかった今、フェザームーン・ストロングホールドへ戻り、ここで見つかったことをジェネラル・シャンドリス・フェザームーンに報告する時が来た。" },
    { id = "quest:2935:description", html = false,
      ja = "broodguardsの毒液は、お前が最初に持ってきた毒液ほど強力ではなかった。別の蜘蛛から採れたものに違いない。\n\nあの毒液の新鮮なサンプルが欲しい。それがどこから来たのかを突き止めるには、Witherbarkをよく知るトロールに相談しなければならん――Sen'jin VillageのMaster Gadrinだ。Durotarへ行ってGadrinと話せ。運がよければ、Witherbarksがどこから毒液を得ているのか知っているだろう。",
      out = "ブルードガードの毒液は、お前が最初に持ってきた毒液ほど強力ではなかった。別の蜘蛛から採れたものに違いない。\n\nあの毒液の新鮮なサンプルが欲しい。それがどこから来たのかを突き止めるには、ウィザーバークをよく知るトロールに相談しなければならん――センジン・ヴィレッジのマスター・ガドリンだ。デュロターへ行ってガドリンと話せ。運がよければ、ウィザーバークがどこから毒液を得ているのか知っているだろう。" },
    { id = "quest:2979:completion", html = false,
      ja = "この宝珠はGordunni族に関する知識を明かしてくれるでしょう……そして奴らの破滅を計画する際に用いるつもりです、{name}。",
      out = "この宝珠はゴーダニ族に関する知識を明かしてくれるでしょう……そして奴らの破滅を計画する際に用いるつもりです、{name}。" },
    { id = "quest:3063:title", html = false,
      ja = "Northspring族への復讐",
      out = "ノーススプリング族への復讐" },
    { id = "quest:310:completion", html = false,
      ja = "Thunderbrewの樽の間にMarlethのBarleybrew Scalderの樽を素早く置いてきてくれたようだな。",
      out = "サンダーブリューの樽の間にマーレスのバーリーブルー・スカルダーの樽を素早く置いてきてくれたようだな。" },
    { id = "quest:321:completion", html = false,
      ja = "この箱は水浸しで、側板が壊れている。内側にも外側にも多くの爪痕が刻まれ……まるでMurlocが中を漁って宝を盗んでいったかのようだ。\n\nだが箱の奥深くに、Lightforge Ingotがただ一つ押し込まれている。残念ながら、武器を作るだけの金属を得るには、さらに多くが必要になるだろう。",
      out = "この箱は水浸しで、側板が壊れている。内側にも外側にも多くの爪痕が刻まれ……まるでマーロックが中を漁って宝を盗んでいったかのようだ。\n\nだが箱の奥深くに、ライトフォージ・インゴットがただ一つ押し込まれている。残念ながら、武器を作るだけの金属を得るには、さらに多くが必要になるだろう。" },
    { id = "quest:3380:description", html = false,
      ja = "この世には安らげぬ魂がいる、{name}。孤独によって穢され、古の悪に縛られた魂が……\n\n大地の奥深くにある場所の話を聞いたことがある――私がこれまで見たこともない強大な力によって、そこへ追放された場所だ。\n\nその場所、Sunken Templeについてもっと知りたければ、Marvon Rivetseekerというゴブリンを訪ねるといい。彼は世界の多くの古代遺跡を研究してきた者で、最後に聞いた話では、Tanarisのトロールの遺跡を調べるためにRatchetの家を出たそうだ。",
      out = "この世には安らげぬ魂がいる、{name}。孤独によって穢され、古の悪に縛られた魂が……\n\n大地の奥深くにある場所の話を聞いたことがある――私がこれまで見たこともない強大な力によって、そこへ追放された場所だ。\n\nその場所、サンクン・テンプルについてもっと知りたければ、マーヴォン・リベットシーカーというゴブリンを訪ねるといい。彼は世界の多くの古代遺跡を研究してきた者で、最後に聞いた話では、タナリスのトロールの遺跡を調べるためにラチェットの家を出たそうだ。" },
    { id = "quest:3506:progress", html = false,
      ja = "blood elfの裏切り者どもの殺戮は進んでいるか、{name}? 何か成果はあったか?\n\nお前こそがあの犬を跪かせるほど強い者であることを願っているぞ! あの女がしてきたことを思えば、苦痛に満ちた死以外にふさわしいものはない!",
      out = "ブラッド・エルフの裏切り者どもの殺戮は進んでいるか、{name}? 何か成果はあったか?\n\nお前こそがあの犬を跪かせるほど強い者であることを願っているぞ! あの女がしてきたことを思えば、苦痛に満ちた死以外にふさわしいものはない!" },
    { id = "quest:358:completion", html = false,
      ja = "お見事、{name}。Scourgeなんかにあの亡骸を渡すと思ったら大きな間違いだ。そしてRot Hideどもから集めてくれた液体を我らの研究所で調べてみるとしよう。何か秘密がわかるかもしれん。\n\nお見事、と言ったが戦いはまだまだ続く。戦いはお前がForsakenにとってどれだけ価値があるかを証明する機会をより多く与えてくれるだろう。",
      out = "お見事、{name}。スコージなんかにあの亡骸を渡すと思ったら大きな間違いだ。そしてロット・ハイドどもから集めてくれた液体を我らの研究所で調べてみるとしよう。何か秘密がわかるかもしれん。\n\nお見事、と言ったが戦いはまだまだ続く。戦いはお前がフォーセイクンにとってどれだけ価値があるかを証明する機会をより多く与えてくれるだろう。" },
    { id = "quest:36:progress", html = false,
      ja = "あのVerna Furlbrowがいなくなるのは本当に寂しいよ。ここへ来る途中で、まさか彼女に会ったりはしなかったよね？",
      out = "あのヴァーナ・ファールブロウがいなくなるのは本当に寂しいよ。ここへ来る途中で、まさか彼女に会ったりはしなかったよね？" },
    { id = "quest:3821:description", html = false,
      ja = "３週間前Sha'niはBurning SteppesのFiregut ogreどもの奇妙な儀式のうわさを確認するために調査へ出た。\n\nGoretoothは小隊の誰とも連絡がつかないそうだ。そして私に目下の任務に集中するのが一番だといった。馬鹿なことを言うな！私の妻だぞ！\n\n{name}、私はここを離れることができない。しかしSha'niの身に何が起きたか知りたい。Burning Steppesへ行き、彼女を捜してほしい。",
      out = "３週間前シャニはバーニング・ステップのファイアガット・オーガどもの奇妙な儀式のうわさを確認するために調査へ出た。\n\nゴアトゥースは小隊の誰とも連絡がつかないそうだ。そして私に目下の任務に集中するのが一番だといった。馬鹿なことを言うな！私の妻だぞ！\n\n{name}、私はここを離れることができない。しかしシャニの身に何が起きたか知りたい。バーニング・ステップへ行き、彼女を捜してほしい。" },
    { id = "quest:3924:completion", html = false,
      ja = "マニュアル手に入れたのか! 読んでSamophlangeの直し方を調べるのが待ちきれないよ! RatchetでSputtervalveと話したんだけど……あいつ、あんたが助けてくれたことに感謝しててさ、お礼したがってたぜ。\n\nオレもあんたには感謝してるよ。今度これを修理したら、知らせるよ……",
      out = "マニュアル手に入れたのか! 読んでサモフランジの直し方を調べるのが待ちきれないよ! ラチェットでスパッターヴァルヴと話したんだけど……あいつ、あんたが助けてくれたことに感謝しててさ、お礼したがってたぜ。\n\nオレもあんたには感謝してるよ。今度これを修理したら、知らせるよ……" },
    { id = "quest:4102:objectives", html = false,
      ja = "Blood Amberを$N1個、FelwoodのMaybess Riverbreezeのところへ持って行って下さい。",
      out = "ブラッド・アンバーを$N1個、フェルウッドのメイベス・リヴァーブリーズのところへ持って行って下さい。" },
    { id = "quest:4143:description", html = false,
      ja = "正直なところ、{name}、旅の中でこんな植物は見たことがないよ。そのクレーターへ行ってみるべきかもしれないな……\n\nいずれにせよ、Muiginが探しているものはちょうど分かっていると思う――Atal'ai hazeだ。ひどい代物で、集めるのも大変だが、あの小さな怪物どもを操るにはまさにうってつけだ。\n\nSwamp of SorrowsにあるAtal'Hakkarの神殿へ行く必要がある。Atal'ai Hazeは、そこにいるdeep lurkers、murk worms、oozesから集められるよ。幸運を祈る、{name}！",
      out = "正直なところ、{name}、旅の中でこんな植物は見たことがないよ。そのクレーターへ行ってみるべきかもしれないな……\n\nいずれにせよ、ムイギンが探しているものはちょうど分かっていると思う――アタライ・ヘイズだ。ひどい代物で、集めるのも大変だが、あの小さな怪物どもを操るにはまさにうってつけだ。\n\nスワンプ・オブ・ソロウにあるアタルハッカーの神殿へ行く必要がある。アタライ・ヘイズは、そこにいるディープ・ラーカー、マーク・ワーム、ウーズから集められるよ。幸運を祈る、{name}！" },
    { id = "quest:4265:description", html = false,
      ja = "触れると莢がいくらか割れ開き、驚いたことにまだ生きているナイトエルフの男性が現れた。ひどく呆然としてはいるが、健康状態は良さそうだ。莢から下ろしてやると、彼は意識を取り戻した。\n\n「Eluneに感謝を――助けてくれたんだね、友よ！ぼ……僕はRaschal。この虫たちに襲われて、気がついたらこの莢の中で体が動かなくなっていたんだ。Strongholdから送られてきたのかい？」\n\nどうやら、行方不明の伝令を見つけたようだ！",
      out = "触れると莢がいくらか割れ開き、驚いたことにまだ生きているナイトエルフの男性が現れた。ひどく呆然としてはいるが、健康状態は良さそうだ。莢から下ろしてやると、彼は意識を取り戻した。\n\n「エルーンに感謝を――助けてくれたんだね、友よ！ぼ……僕はラスカル。この虫たちに襲われて、気がついたらこの莢の中で体が動かなくなっていたんだ。ストロングホールドから送られてきたのかい？」\n\nどうやら、行方不明の伝令を見つけたようだ！" },
    { id = "quest:4381:title", html = false,
      ja = "Crystal Restore",
      out = "クリスタル・リストア" },
    { id = "quest:4490:description", html = false,
      ja = "その忍耐と勤勉には報酬を与えよう。だが覚えておけ、Felsteedを召喚する能力は、今後ははるかに得難いものとなる。自ら勝ち取らねばならぬ……そして、それは容易ではない。\n\n今は、その生き物を召喚する力を持って行き、思うままに使うがいい。",
      out = "その忍耐と勤勉には報酬を与えよう。だが覚えておけ、フェルスティードを召喚する能力は、今後ははるかに得難いものとなる。自ら勝ち取らねばならぬ……そして、それは容易ではない。\n\n今は、その生き物を召喚する力を持って行き、思うままに使うがいい。" },
    { id = "quest:4603:progress", html = false,
      ja = "Sparklematic 5200は空っぽで、きれいにする汚れのこびりついた品と、動かすための銀貨3枚を待っている!",
      out = "スパークルマティック 5200は空っぽで、きれいにする汚れのこびりついた品と、動かすための銀貨3枚を待っている!" },
    { id = "quest:473:description", html = false,
      ja = "{name}。Dragonmawのオーク氏族は、Algazだけでなくほかでも力を見せつけている。Captain Stoutfistが、このオークどもに立ち向かう力を貸してくれる者と話したいそうだ。彼は砦の中の作戦室にいる。",
      out = "{name}。ドラゴンマウのオーク氏族は、アルガズだけでなくほかでも力を見せつけている。キャプテン・スタウトフィストが、このオークどもに立ち向かう力を貸してくれる者と話したいそうだ。彼は砦の中の作戦室にいる。" },
    { id = "quest:4808:title", html = false,
      ja = "Felnok Steelspring",
      out = "フェルノック・スティールスプリング" },
    { id = "quest:493:description", html = false,
      ja = "Royal Apothecary Societyは、New Plagueを開発するようDark Ladyから強い圧力を受けている。我々は熱心に取り組み、大きな進展を遂げてきた。Society内で情報を共有すれば、成功ははるかに早く達成できると我々は考えている。\n\nそういうわけで、私の最新の研究成果を、Hillsbrad Foothillsに抱かれた小さな町Tarren MillのApothecary Lydonに届けてもらいたい。長い旅になるだろう。\n\n南へ向かい、道から外れるな。標識をよく見て進め！",
      out = "ロイヤル・アポセカリー・ソサエティは、ニュー・プレイグを開発するようダーク・レディから強い圧力を受けている。我々は熱心に取り組み、大きな進展を遂げてきた。ソサエティ内で情報を共有すれば、成功ははるかに早く達成できると我々は考えている。\n\nそういうわけで、私の最新の研究成果を、ヒルズブラッド・フットヒルに抱かれた小さな町ターレン・ミルのアポセカリー・ライドンに届けてもらいたい。長い旅になるだろう。\n\n南へ向かい、道から外れるな。標識をよく見て進め！" },
    { id = "quest:5041:progress", html = false,
      ja = "suppliesの捜索はどうだ、{name}? quilboarどもなど、お前の力なら容易く倒せるだろう。",
      out = "サプライの捜索はどうだ、{name}? キルボアどもなど、お前の力なら容易く倒せるだろう。" },
    { id = "quest:5093:title", html = false,
      ja = "出撃命令: The Plaguelands!",
      out = "出撃命令: プレイグランド!" },
    { id = "quest:5158:progress", html = false,
      ja = "あなたはRatchetへの道を探しているただの旅人ではないようですね。さあ、私たちの野営地で座って休んでください。準備ができたら声をかけてください。",
      out = "あなたはラチェットへの道を探しているただの旅人ではないようですね。さあ、私たちの野営地で座って休んでください。準備ができたら声をかけてください。" },
    { id = "quest:5223:progress", html = false,
      ja = "Writhing Hauntの大釜から採ったサンプルの分析に成功すれば、Scourgeに壊滅的な対抗薬を浴びせる三つ目の手段が手に入る!",
      out = "ライジング・ホーントの大釜から採ったサンプルの分析に成功すれば、スコージに壊滅的な対抗薬を浴びせる三つ目の手段が手に入る!" },
    { id = "quest:5281:objectives", html = false,
      ja = "Eganを探し出して下さい。彼が最後に目撃されたのはStratholmeの周りだったということだけが分かっています。",
      out = "イーガンを探し出して下さい。彼が最後に目撃されたのはストラトホルムの周りだったということだけが分かっています。" },
    { id = "quest:5421:objectives", html = false,
      ja = "Shadowprey Village 付近の罠から Shellfish を5匹集める。",
      out = "シャドウプレイ・ヴィレッジ 付近の罠から シェルフィッシュ を5匹集める。" },
    { id = "quest:5521:progress", html = false,
      ja = "ごきげんよう、偉大なる{class}よ! 頼んでおいたvalor tokensは持ってきてくれたか? 渡してくれれば、君専用のChromatic Mantle of the Dawnを授けよう。",
      out = "ごきげんよう、偉大なる{class}よ! 頼んでおいたヴァラー・トークンは持ってきてくれたか? 渡してくれれば、君専用のクロマティック・マントル・オブ・ザ・ドーンを授けよう。" },
    { id = "quest:5622:completion", html = false,
      ja = "{name}、Shandaがあなたを送り出してくれて嬉しいですよ。若い司祭にEluneの御技を教えることは、満ち足りた思いを与えてくれますから。",
      out = "{name}、シャンダがあなたを送り出してくれて嬉しいですよ。若い司祭にエルーンの御技を教えることは、満ち足りた思いを与えてくれますから。" },
    { id = "quest:5674:completion", html = false,
      ja = "Eluneと私たちの民に身を捧げたことで、あなたは誰もが到達できるわけではない境地に至りました。その献身に対して、さらに大きな力を授けるのが習わしです。受け入れますか?",
      out = "エルーンと私たちの民に身を捧げたことで、あなたは誰もが到達できるわけではない境地に至りました。その献身に対して、さらに大きな力を授けるのが習わしです。受け入れますか?" },
    { id = "quest:5804:title", html = false,
      ja = "Araj's Scarab",
      out = "アラージズ・スカラブ" },
    { id = "quest:5904:description", html = false,
      ja = "シロアリが手に入ったから、この鋼で補強した樽をHearthglenの南にあるNorthridge Lumber Millへ持って行ってくれ――町へ上っていく道の西側にある。\n\n着いたら、製材所の真ん中に樽を置け。木箱の上のような適当な場所を見つけて、それから樽を開けるんだ。あとはシロアリが仕事をして、製材所をCrusadeにとって役に立たないものにしてくれるはずだ。",
      out = "シロアリが手に入ったから、この鋼で補強した樽をハースグレンの南にあるノースリッジ・ランバー・ミルへ持って行ってくれ――町へ上っていく道の西側にある。\n\n着いたら、製材所の真ん中に樽を置け。木箱の上のような適当な場所を見つけて、それから樽を開けるんだ。あとはシロアリが仕事をして、製材所をクルセードにとって役に立たないものにしてくれるはずだ。" },
    { id = "quest:6025:completion", html = false,
      ja = "やってくれたな、{name}! ありがとう!\n\nできるだけ早くEllingに……いや、Stormwindに戻るよ。ほら、この金を受け取ってくれ。せめてものお礼だ。君は同胞の誇りだよ、{name}。ありがとう、幸運を祈る。",
      out = "やってくれたな、{name}! ありがとう!\n\nできるだけ早くエリングに……いや、ストームウィンドに戻るよ。ほら、この金を受け取ってくれ。せめてものお礼だ。君は同胞の誇りだよ、{name}。ありがとう、幸運を祈る。" },
    { id = "quest:6103:objectives", html = false,
      ja = "DarnassusのCenarion EnclaveにいるJocasteと話す。",
      out = "ダーナサスのセナリウス・エンクレイヴにいるジョカステと話す。" },
    { id = "quest:6187:description", html = false,
      ja = "この世界にレンジャーロードがどれほどいるか知っているか？人間のレンジャーロードがこれまでに何人存在したか？\n\nNathanosの功績は前例のないものだった。彼は戦術の天才で、十年にわたる戦いでAllianceに勝利をもたらしてきた。\n\nそれが今や……Forsakenの勇者とは。\n\nいや。こんなことがあってはならん。秩序を取り戻さねばならん。\n\n軍を集めよ、{name}。軍を率いてPlaguesへ戻り、Blightcallerを滅ぼすのだ。\n\n幸運を祈る、{name}。この戦いには、まことにそれが必要になるだろう。",
      out = "この世界にレンジャーロードがどれほどいるか知っているか？人間のレンジャーロードがこれまでに何人存在したか？\n\nナサノスの功績は前例のないものだった。彼は戦術の天才で、十年にわたる戦いでアライアンスに勝利をもたらしてきた。\n\nそれが今や……フォーセイクンの勇者とは。\n\nいや。こんなことがあってはならん。秩序を取り戻さねばならん。\n\n軍を集めよ、{name}。軍を率いてプレイグへ戻り、ブライトコーラーを滅ぼすのだ。\n\n幸運を祈る、{name}。この戦いには、まことにそれが必要になるだろう。" },
    { id = "quest:6362:description", html = false,
      ja = "安い運賃でThunder Bluffまで乗せてやろう。Thunder Bluffまで行くのに、これより速い方法はないぞ!\n\nもしそうしたいなら、準備ができてからまた俺に話しかけてくれ。\n\n皮の束をAhanuのところへ持って行くんなら、彼はThunder Bluffのwind riderタワーのふもとにある、「Hewa's Armory」にいたと思う。wind riderタワーってのは、ちょうど着陸したところだ!",
      out = "安い運賃でサンダー・ブラフまで乗せてやろう。サンダー・ブラフまで行くのに、これより速い方法はないぞ!\n\nもしそうしたいなら、準備ができてからまた俺に話しかけてくれ。\n\n皮の束をアハヌのところへ持って行くんなら、彼はサンダー・ブラフのウィンド・ライダータワーのふもとにある、「ヒューワズ・アーモリー」にいたと思う。ウィンド・ライダータワーってのは、ちょうど着陸したところだ!" },
    { id = "quest:645:progress", html = false,
      ja = "Trollbaneの墓の表面の石に刻まれた模様は、Sigil of Ignaeusの光る線と一致している……",
      out = "トロルベインの墓の表面の石に刻まれた模様は、シジル・オブ・イグナエウスの光る線と一致している……" },
    { id = "quest:6563:title", html = false,
      ja = "Aku'Mai のエッセンス",
      out = "アクマイ のエッセンス" },
    { id = "quest:664:description", html = false,
      ja = "ああ、ひどい人生だ。本当なら今ごろ水の墓にいるはずで、こんな焚き火のそばで新鮮な空気を吸ってるはずじゃねえんだ。\n\n乗組員たちは、俺の美しいMaiden's Follyを救おうと必死だった。あいつらに祝福を、あいつらの心に祝福を。\n\nO'Breenは無事に岸にたどり着いたが、俺たちはそう運が良くなかった。誓って言うが、海がそのまま俺たちを沈めちまったんだ。\n\nついさっきまで浮いてたかと思えば、次の瞬間には水が流れ込んでくる。それにあの獣ども！ 生き残った者をみんな殺しやがった。おぞましいnagaのクズどもめ。俺は気を失って、気がついたらここで助けられてたんだ。\n\nあの獣どもを皆殺しにしてやりたい。",
      out = "ああ、ひどい人生だ。本当なら今ごろ水の墓にいるはずで、こんな焚き火のそばで新鮮な空気を吸ってるはずじゃねえんだ。\n\n乗組員たちは、俺の美しいメイデンズ・フォリーを救おうと必死だった。あいつらに祝福を、あいつらの心に祝福を。\n\nオブリーンは無事に岸にたどり着いたが、俺たちはそう運が良くなかった。誓って言うが、海がそのまま俺たちを沈めちまったんだ。\n\nついさっきまで浮いてたかと思えば、次の瞬間には水が流れ込んでくる。それにあの獣ども！ 生き残った者をみんな殺しやがった。おぞましいナーガのクズどもめ。俺は気を失って、気がついたらここで助けられてたんだ。\n\nあの獣どもを皆殺しにしてやりたい。" },
    { id = "quest:6846:progress", html = false,
      ja = "我が部隊は補給を終え、攻撃の準備ができている。あとはNoreg Stormpikeからの命令さえあれば、奴らを戦場へ送り込むぞ！",
      out = "我が部隊は補給を終え、攻撃の準備ができている。あとはノレグ・ストームパイクからの命令さえあれば、奴らを戦場へ送り込むぞ！" },
    { id = "quest:7001:description", html = false,
      ja = "この谷の戦いで兵士たちは痛手を負った。部隊を再生しなければならない!\n\n厩舎をいっぱいにできれば、Wolf Ridersが再び戦場へと駆け出ていくことができる。\n\nこの口輪を持って行き、森の近くに住むfrostwolfを捕らえてほしい。狼を見つけたら、馴らすために口輪を使え。馴らした狼は、厩舎へ繋げるように私のところへ連れ帰るのだ。\n\n充分な数の狼が厩舎に揃えば、Wolf Ridersは再び前線の警戒に加わることができよう。",
      out = "この谷の戦いで兵士たちは痛手を負った。部隊を再生しなければならない!\n\n厩舎をいっぱいにできれば、ウルフ・ライダーが再び戦場へと駆け出ていくことができる。\n\nこの口輪を持って行き、森の近くに住むフロストウルフを捕らえてほしい。狼を見つけたら、馴らすために口輪を使え。馴らした狼は、厩舎へ繋げるように私のところへ連れ帰るのだ。\n\n充分な数の狼が厩舎に揃えば、ウルフ・ライダーは再び前線の警戒に加わることができよう。" },
    { id = "quest:70:title", html = false,
      ja = "Stalvanの伝説",
      out = "スタルヴァンの伝説" },
    { id = "quest:7282:description", html = false,
      ja = "奴を苦しみから解放してやらねばならん、兵士よ！奴は自分が何をしているのか分かっていないのだ。恐るべきBanshee Queenの心なき下僕に成り果ててしまった。\n\nField of Strifeを越え、Frostwolfの領地の奥深くへ進め。私の兄弟を見つけ、滅ぼしてくれ。奴の苦しみに終止符を打たねばならん。",
      out = "奴を苦しみから解放してやらねばならん、兵士よ！奴は自分が何をしているのか分かっていないのだ。恐るべきバンシー・クイーンの心なき下僕に成り果ててしまった。\n\nフィールド・オブ・ストライフを越え、フロストウルフの領地の奥深くへ進め。私の兄弟を見つけ、滅ぼしてくれ。奴の苦しみに終止符を打たねばならん。" },
    { id = "quest:7487:objectives", html = false,
      ja = "Blackrock DepthsにあるMolten Coreの入口ポータルへ行き、Core Fragmentを回収する。Core Fragmentを回収したら、Blackrock MountainのLothos Riftwakerのところへ戻って下さい。",
      out = "ブラックロック・デプスにあるモルテン・コアの入口ポータルへ行き、コア・フラグメントを回収する。コア・フラグメントを回収したら、ブラックロック・マウンテンのロソス・リフトウェイカーのところへ戻って下さい。" },
    { id = "quest:7601:title", html = false,
      ja = "Nibyの命令",
      out = "ナイビーの命令" },
    { id = "quest:7649:title", html = false,
      ja = "Enchanted Thorium Platemail: 第一巻",
      out = "エンチャンテッド・ソーリウム・プレートメイル: 第一巻" },
    { id = "quest:775:objectives", html = false,
      ja = "Thunder BluffのCairne Bloodhoofと話してください。",
      out = "サンダー・ブラフのケーアン・ブラッドフーフと話してください。" },
    { id = "quest:7818:completion", html = false,
      ja = "素晴らしい――これはすぐに役立てますよ、約束します。改めてご協力に感謝します! あなたがいなければ、私たちは本当に途方に暮れていたでしょう。\n\nこれだけ寄付をしてくださったのですから、今後もruneclothを寄付していただけるなら、喜んで受け付けます。必ず私に声をかけてください。あなたの善行が見過ごされないよう、私が責任を持って取り計らいます!",
      out = "素晴らしい――これはすぐに役立てますよ、約束します。改めてご協力に感謝します! あなたがいなければ、私たちは本当に途方に暮れていたでしょう。\n\nこれだけ寄付をしてくださったのですから、今後もルーンクロスを寄付していただけるなら、喜んで受け付けます。必ず私に声をかけてください。あなたの善行が見過ごされないよう、私が責任を持って取り計らいます!" },
    { id = "quest:786:description", html = false,
      ja = "声を落とせ、{class}殿。Kolkar centaurどもはKolkar Cragという西にある峰のすぐ向こうにたむろしている。\n\n昨夜やつらが襲撃に出た隙に、奴らの村に忍び込んだ。そしてあの薄汚れた野獣どもがDurotarのオークやトロールに対して３段階にわたる襲撃を計画していることを知った。\n\nそんなことをさせるわけにはいかん。たぶんあんたはKolkar Cragに潜入する能力はもってるだろう。奴らの計画書を処分してくれ。\n\n見たところ、そいつは３人のリーダーの下に別々に置かれていたようだ。",
      out = "声を落とせ、{class}殿。コルカー・セントールどもはコルカー・クラッグという西にある峰のすぐ向こうにたむろしている。\n\n昨夜やつらが襲撃に出た隙に、奴らの村に忍び込んだ。そしてあの薄汚れた野獣どもがデュロターのオークやトロールに対して３段階にわたる襲撃を計画していることを知った。\n\nそんなことをさせるわけにはいかん。たぶんあんたはコルカー・クラッグに潜入する能力はもってるだろう。奴らの計画書を処分してくれ。\n\n見たところ、そいつは３人のリーダーの下に別々に置かれていたようだ。" },
    { id = "quest:7927:objectives", html = false,
      ja = "Darkmoon Faireが町へやって来た時に、Portals Deckを返却して下さい。",
      out = "ダークムーン・フェアが町へやって来た時に、ポータル・デッキを返却して下さい。" },
    { id = "quest:8043:progress", html = false,
      ja = "{name}殿、戻ったか! Molthorがお前の功績を王に伝えている。お前の名はSouth Seasにまで知れ渡っているぞ。いつの日か、お前は伝説の{class}、後世に語り継がれる物語となるかもしれんな。\n\nもう一度その力を増幅してやれるよう、護符を渡してくれ。",
      out = "{name}殿、戻ったか! モルソーがお前の功績を王に伝えている。お前の名はサウス・シーにまで知れ渡っているぞ。いつの日か、お前は伝説の{class}、後世に語り継がれる物語となるかもしれんな。\n\nもう一度その力を増幅してやれるよう、護符を渡してくれ。" },
    { id = "quest:8073:description", html = false,
      ja = "私の目はとうの昔に見えなくなったが、惜しいとは思わない。我らのような部族――まとう装束が地位と目的を示す部族――の中でさえ、最も力ある衣は、ただの目には見えない力を放っているのだ。Zandalarの狂人が大事にするチュニックも例外ではなく、彼らが操ることのできる混沌と狂気の生の力を放っている。\n\n私が必要とするParagons of PowerはZul'Gurubにある。私の求めるものを持ってくれば、お前自身の伝説のチュニックで報いてやろう……狂気を織りなす者にふさわしい一着でな。",
      out = "私の目はとうの昔に見えなくなったが、惜しいとは思わない。我らのような部族――まとう装束が地位と目的を示す部族――の中でさえ、最も力ある衣は、ただの目には見えない力を放っているのだ。ザンダラーの狂人が大事にするチュニックも例外ではなく、彼らが操ることのできる混沌と狂気の生の力を放っている。\n\n私が必要とするパラゴン・オブ・パワーはズルグラブにある。私の求めるものを持ってくれば、お前自身の伝説のチュニックで報いてやろう……狂気を織りなす者にふさわしい一着でな。" },
    { id = "quest:8150:completion", html = false,
      ja = "Gromのフルネーム、Grommashは「巨人の心」を意味する。Mannorothにただ一人で立ち向かうには、それ以上のものが必要だった。大族長が、オークの呪いはGromに始まりGromに終わったと言ったのが、一番うまい言い方だと思う。Gromの犠牲、そしておそらくは贖罪が、今日のHordeが湧き出る源となったのは、ふさわしいことだ。\n\nありがとう、{name}。お前は今日、偉大な英雄に敬意を捧げ、彼の魂とHarvest Festivalの精神を称えてくれた。",
      out = "グロムのフルネーム、グロマッシュは「巨人の心」を意味する。マノロスにただ一人で立ち向かうには、それ以上のものが必要だった。大族長が、オークの呪いはグロムに始まりグロムに終わったと言ったのが、一番うまい言い方だと思う。グロムの犠牲、そしておそらくは贖罪が、今日のホードが湧き出る源となったのは、ふさわしいことだ。\n\nありがとう、{name}。お前は今日、偉大な英雄に敬意を捧げ、彼の魂とハーベスト・フェスティバルの精神を称えてくれた。" },
    { id = "quest:81770:description", html = false,
      ja = "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでBough ShadowのEmerald Dream Portalを通り、Forest SongのNightmare Incursionへ向かってくれ。そこでdragonkinを倒し、私のもとへ戻ってくれ。",
      out = "悪魔どもがここで我々の気を引いている間に、エメラルド・ドリームは悪夢へと堕落させられつつある。急いでバウ・シャドウのエメラルド・ドリーム・ポータルを通り、フォレスト・ソングのナイトメア・インカージョンへ向かってくれ。そこでドラゴンキンを倒し、私のもとへ戻ってくれ。" },
    { id = "quest:81864:description", html = false,
      ja = "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、Ruins of RavenwindのNightmare Incursionへ向かってくれ。そこでharpy Screedを手に入れ、私に届けてくれ。",
      out = "悪魔どもがここで我々の気を引いている間に、エメラルド・ドリームは悪夢へと堕落させられつつある。急いでドリーム・バウのエメラルド・ドリーム・ポータルを通り、ルイン・オブ・レイヴンウィンドのナイトメア・インカージョンへ向かってくれ。そこでハーピー・スクリードを手に入れ、私に届けてくれ。" },
    { id = "quest:8252:objectives", html = false,
      ja = "Enchanted Coral 6つを集め、Archmage Xylemのところへ持ち帰って下さい。",
      out = "エンチャンテッド・コーラル 6つを集め、アークメイジ・ザイレムのところへ持ち帰って下さい。" },
    { id = "quest:8297:objectives", html = false,
      ja = "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、Refuge PointeのSergeant Maclearのところへ持って行って下さい。",
      out = "アラシ・ベイスンの戦いに勝ち、アラシ・リソース・クレートを手に入れて、レフュージ・ポイントのサージェント・マクリアのところへ持って行って下さい。" },
    { id = "quest:8359:completion", html = false,
      ja = "あなたは本当に力強いですね、あははは! いいでしょう、気前よく応じて下さってありがとう。これがあなたのキャンディですよ。\n\n楽しくHallow's Endを過ごして下さいね、{name}!",
      out = "あなたは本当に力強いですね、あははは! いいでしょう、気前よく応じて下さってありがとう。これがあなたのキャンディですよ。\n\n楽しくハロウズ・エンドを過ごして下さいね、{name}!" },
    { id = "quest:8402:objectives", html = false,
      ja = "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。",
      out = "ウォーソング・ガルチ・マーク・オブ・オナーを$N1個、戦場の外にいるアライアンス・ブリガディア・ジェネラルのところへ持って行って下さい。" },
    { id = "quest:84189:title", html = false,
      ja = "Anthionの遺言",
      out = "アンシオンの遺言" },
    { id = "quest:8439:completion", html = false,
      ja = "Arathiの資源を確保するのは重要な任務だ! よくやった、{name}。",
      out = "アラシの資源を確保するのは重要な任務だ! よくやった、{name}。" },
    { id = "quest:8509:progress", html = false,
      ja = "何だって? はっきり言ってくれ、{class}! 頼んでおいたArthas' Tearsの積荷は手に入れたのか?",
      out = "何だって? はっきり言ってくれ、{class}! 頼んでおいたアーサス・ティアの積荷は手に入れたのか?" },
    { id = "quest:8578:completion", html = false,
      ja = "見事だ! さて、あの500ポンドの鶏と『Draconic For Dummies???』のVolume IIはどこへやったかな? ああ、それと、君の骨折りに少しばかりの物があるぞ!",
      out = "見事だ! さて、あの500ポンドの鶏と『ドラコニック・フォー・ダミー???』のボリューム2はどこへやったかな? ああ、それと、君の骨折りに少しばかりの物があるぞ!" },
    { id = "quest:86577:description", html = false,
      ja = "Hyjalから降り注ぐ堕落は山の水を通して流れ、この森のあらゆるものに染み込んでいます。その水を飲んだ生き物たちは、堕落を体内に取り込んでしまうのです。それによって彼らは獰猛になり、病に冒され、恐れを知らなくなります。\n\nこうした影響に対抗するには、まずそれを理解しなければなりません。そのためには、冒された者たちのサンプルが必要です。\n\n狼や熊のputrescent organsのサンプルがいくつかあれば十分でしょう。急ぐ必要はありません。Felwoodにはそうした生き物がたくさんいますから。",
      out = "ハイジャルから降り注ぐ堕落は山の水を通して流れ、この森のあらゆるものに染み込んでいます。その水を飲んだ生き物たちは、堕落を体内に取り込んでしまうのです。それによって彼らは獰猛になり、病に冒され、恐れを知らなくなります。\n\nこうした影響に対抗するには、まずそれを理解しなければなりません。そのためには、冒された者たちのサンプルが必要です。\n\n狼や熊のピュートレセント・オーガンのサンプルがいくつかあれば十分でしょう。急ぐ必要はありません。フェルウッドにはそうした生き物がたくさんいますから。" },
    { id = "quest:8697:objectives", html = false,
      ja = "Qiraji Ceremonial Ring・Obsidian Idol 2つ・Silver Scarab 5つ・Bone Scarab 5つをSilithusのWindcaller Yessendraに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから称賛(Honored)の評判を獲得していなければなりません。",
      out = "キラジ・セレモニアル・リング・オブシディアン・アイドル 2つ・シルバー・スカラブ 5つ・ボーン・スカラブ 5つをシリサスのウィンドコーラー・イェッセンドラに渡して下さい。\n\nこのクエストを達成するには、セナリウス・サークルから称賛(オナード)の評判を獲得していなければなりません。" },
    { id = "quest:8748:progress", html = false,
      ja = "Kalimdorの子らを守り続けてきたそなたの働きは、確かに認められた。その力を高められるよう、印章の指輪を我に渡すがよい。",
      out = "カリムドアの子らを守り続けてきたそなたの働きは、確かに認められた。その力を高められるよう、印章の指輪を我に渡すがよい。" },
    { id = "quest:8820:progress", html = false,
      ja = "私は、任務の中でcommendation signetを授かった冒険者から、それを受け取っている。10個ひとまとめで渡してくれるごとに、その行いに対するGnomeregan Exilesでの確かな評価が必ず得られるようにしよう。1個ずつでも受け取るが、評価の割合はずっと低くなる。我々はより大きな功績により強い関心があるが、どんな功績も見過ごされることはない。\n\nそういうわけで、ひとまとめ分を渡す用意があるなら、喜んでそのsignetを受け取ろう。",
      out = "私は、任務の中でコメンデーション・シグネットを授かった冒険者から、それを受け取っている。10個ひとまとめで渡してくれるごとに、その行いに対するノームリガン・エグザイルでの確かな評価が必ず得られるようにしよう。1個ずつでも受け取るが、評価の割合はずっと低くなる。我々はより大きな功績により強い関心があるが、どんな功績も見過ごされることはない。\n\nそういうわけで、ひとまとめ分を渡す用意があるなら、喜んでそのシグネットを受け取ろう。" },
    { id = "quest:8875:description", html = false,
      ja = "この季節になりましたよ、{name}! Lunar Festivalのお祝いに参加してもらうため、Cenarion CircleがAzerothの全住人を招待しています。Lunar Festival Harbingerがちょうどこの街にいますよ。彼女は神聖な月光の輪で示された場所にいます。この休日についての詳細は彼女が教えてくれます。",
      out = "この季節になりましたよ、{name}! ルナー・フェスティバルのお祝いに参加してもらうため、セナリウス・サークルがアゼロスの全住人を招待しています。ルナー・フェスティバル・ハービンジャーがちょうどこの街にいますよ。彼女は神聖な月光の輪で示された場所にいます。この休日についての詳細は彼女が教えてくれます。" },
    { id = "quest:8926:description", html = false,
      ja = "あなたは約束を守って、Muxの作った装置を持ってきてくれた。難を逃れようと考えてあなたを雇うのなら、それに見合う報酬を渡すのが順当だと信じているわ。性能を上げたいベルトとグローブを持ってきてちょうだい。お返しに渡す物は、より優れた物になっていると約束するわ。",
      out = "あなたは約束を守って、マックスの作った装置を持ってきてくれた。難を逃れようと考えてあなたを雇うのなら、それに見合う報酬を渡すのが順当だと信じているわ。性能を上げたいベルトとグローブを持ってきてちょうだい。お返しに渡す物は、より優れた物になっていると約束するわ。" },
    { id = "quest:8969:description", html = false,
      ja = "さて、必要なものは揃った。お前が誰を呼び出すことになるのか話す時だ。\n\nKormokはogreにしてはまともな奴だった。死霊術に手を染めるまではな。それ以来、一団のほとんど全員にとって薄気味悪いことになった。だから、奴が自分のアミュレットの欠片を持って新しい住処、Scholomanceへ戻ったときも、驚きはしなかった。\n\nだが、そこでさえ、いや、おそらくそこだからこそ、奴はspectral assassinsから逃れられなかった。奴らは奴の師、Ras Frostwhisperの目の前で奴を殺したのだ。",
      out = "さて、必要なものは揃った。お前が誰を呼び出すことになるのか話す時だ。\n\nコーモックはオーガにしてはまともな奴だった。死霊術に手を染めるまではな。それ以来、一団のほとんど全員にとって薄気味悪いことになった。だから、奴が自分のアミュレットの欠片を持って新しい住処、スカラマンスへ戻ったときも、驚きはしなかった。\n\nだが、そこでさえ、いや、おそらくそこだからこそ、奴はスペクトラル・アサシンから逃れられなかった。奴らは奴の師、ラス・フロストウィスパーの目の前で奴を殺したのだ。" },
    { id = "quest:9018:title", html = false,
      ja = "Anthionの遺言",
      out = "アンシオンの遺言" },
    { id = "quest:9124:objectives", html = false,
      ja = "Eastern PlaguelandsのLight's Hope ChapelにいるHuntsman Leopoldは、Crypt Fiend Partsを$N1個求めています。",
      out = "イースタン・プレイグランドのライツ・ホープ・チャペルにいるハンツマン・レオポルドは、クリプト・フィーンド・パーツを$N1個求めています。" },
    { id = "quest:91745:objectives", html = false,
      ja = "Northshire ValleyのEcho Ridge Mineの外にいるKelsey Fargoと話してください。",
      out = "ノースシャイア・バレーのエコー・リッジ・マインの外にいるケルシー・ファーゴと話してください。" },
    { id = "quest:9197:objectives", html = false,
      ja = "Gnomish Battle Chickenを4個とCraftsman's Writ - Gnomish Battle Chickenを、Eastern PlaguelandsのLight's Hope ChapelにいるPackmaster Stonebruiserのところへ持って行って下さい。",
      out = "ノーミッシュ・バトル・チキンを4個とクラフツマンズ・リット - ノーミッシュ・バトル・チキンを、イースタン・プレイグランドのライツ・ホープ・チャペルにいるパックマスター・ストーンブルーザーのところへ持って行って下さい。" },
    { id = "quest:9233:progress", html = false,
      ja = "それは私が思っている物か?\n\n<Wilhelmはよだれを垂らしているようだ。>",
      out = "それは私が思っている物か?\n\n<ヴィルヘルムはよだれを垂らしているようだ。>" },
    { id = "quest:92479:title", html = false,
      ja = "Scribbled Letter",
      out = "スクリブルド・レター" },
    { id = "quest:92645:objectives", html = false,
      ja = "Gustberry LowlandsでCommander Belguilosを倒してください。",
      out = "ガストベリー・ローランドでコマンダー・ベルギロスを倒してください。" },
    { id = "quest:92841:title", html = false,
      ja = "Valley of Bones",
      out = "バレー・オブ・ボーン" },
    { id = "quest:930:objectives", html = false,
      ja = "Lake Al'Ameth にいる Denalan に glowing fruit を渡して下さい。",
      out = "レイク・アルアメス にいる デナラン に グローイング・フルーツ を渡して下さい。" },
    { id = "quest:93422:title", html = false,
      ja = "Blackthorneの消灯",
      out = "ブラックソーンの消灯" },
    { id = "quest:93740:progress", html = false,
      ja = "Al'Akethはあまりにも長く血塗られた狂信を続けてきた。これは奴らが受ける報いの始まりにすぎない。",
      out = "アルアケスはあまりにも長く血塗られた狂信を続けてきた。これは奴らが受ける報いの始まりにすぎない。" },
    { id = "quest:94216:title", html = false,
      ja = "Craftsman's Writ: Elixir of Lesser Agility",
      out = "クラフツマンズ・リット: エリクサー・オブ・レッサー・アジリティ" },
    { id = "quest:94286:title", html = false,
      ja = "Craftsman's Writ: Flash Bomb",
      out = "クラフツマンズ・リット: フラッシュ・ボム" },
    { id = "quest:94357:description", html = false,
      ja = "<色あせたインクで書かれたこのメモには、Cenarion Herb Bagを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>",
      out = "<色あせたインクで書かれたこのメモには、セナリウス・ハーブ・バッグを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>" },
    { id = "quest:94559:objectives", html = false,
      ja = "Shen'dar HighlandsでAl'Aketh Turncoatを探し出して下さい。",
      out = "シェンダー・ハイランドでアルアケス・ターンコートを探し出して下さい。" },
    { id = "quest:94885:description", html = false,
      ja = "その日誌には、Riverglades中を行き来するTwilight's Hammerの部隊の動きが、細かく丹念に記録されている。\n\n書き手の姿はどこにもないが、この情報は敵の動きを明らかにする助けになるかもしれない。\n\nFarholdeの誰かが、これを見たがるだろう。",
      out = "その日誌には、リヴァーグレイズ中を行き来するトワイライツ・ハンマーの部隊の動きが、細かく丹念に記録されている。\n\n書き手の姿はどこにもないが、この情報は敵の動きを明らかにする助けになるかもしれない。\n\nファーホールドの誰かが、これを見たがるだろう。" },
    { id = "quest:949:objectives", html = false,
      ja = "Master's GlaiveにあるTwilight's Hammerの野営地で手がかりを見つける。",
      out = "マスターズ・グレイヴにあるトワイライツ・ハンマーの野営地で手がかりを見つける。" },
    { id = "quest:95204:objectives", html = false,
      ja = "Crest of LordaeronをUndercityのOran Snakewritheに届けてください。",
      out = "クレスト・オブ・ローデロンをアンダーシティのオラン・スネイクライズに届けてください。" },
    { id = "quest:95426:title", html = false,
      ja = "Rog'marの物資",
      out = "ログマーの物資" },
    { id = "quest:95790:objectives", html = false,
      ja = "Shaper's TerraceでPartially Digested Journal Pagesを$N1枚集める。",
      out = "シェイパーズ・テラスでパーシャリー・ダイジェステッド・ジャーナル・ページを$N1枚集める。" },
    { id = "quest:96028:objectives", html = false,
      ja = "Bolder'okのBal'mogのために、魔法を$N1回使って下さい。",
      out = "ボルダーオックのバルモグのために、魔法を$N1回使って下さい。" },
    { id = "quest:96264:objectives", html = false,
      ja = "Razorfen KraulでCharlga Razorflankを倒し、quilboarの計画に関する情報を集めて下さい。",
      out = "レイザーフェン・クラウルでチャールガ・レイザーフランクを倒し、キルボアの計画に関する情報を集めて下さい。" },
    { id = "quest:96659:objectives", html = false,
      ja = "Supply BundleをBloodhoof Village付近にいるKaga Wildhoofに届けてください。",
      out = "サプライ・バンドルをブラッドフーフ・ヴィレッジ付近にいるカガ・ワイルドフーフに届けてください。" },
    { id = "quest:96984:description", html = false,
      ja = "お前が我々のためを思っているとは限らないが、手が増えるのを断るつもりはない。それに、Dalaranが落ちれば、すべてが道連れになる。お前のUndercityもな。\n\nつまり、お前の後援者も一枚噛みたいと？いいだろう。私の結界を越えられるようにお前の鍵に力を込めてやるから、都市に入れ。中に入ったら、すべてが始まったViolet Citadelで落ち合おう。これだけのことが起きている今、Kirin Torはお前を止める暇もないだろう。\n\n好きなものを漁ればいい。だが何が起きようと、我々の最優先事項は破局を防ぐことだ。",
      out = "お前が我々のためを思っているとは限らないが、手が増えるのを断るつもりはない。それに、ダラランが落ちれば、すべてが道連れになる。お前のアンダーシティもな。\n\nつまり、お前の後援者も一枚噛みたいと？いいだろう。私の結界を越えられるようにお前の鍵に力を込めてやるから、都市に入れ。中に入ったら、すべてが始まったヴァイオレット・シタデルで落ち合おう。これだけのことが起きている今、キリン・トーはお前を止める暇もないだろう。\n\n好きなものを漁ればいい。だが何が起きようと、我々の最優先事項は破局を防ぐことだ。" },
    { id = "quest:971:objectives", html = false,
      ja = "IronforgeのForlorn CavernにいるGerrig Bonegripに、Lorgalis Manuscriptを渡して下さい。",
      out = "アイアンフォージのフォーローン・ケイヴァーンにいるゲリッグ・ボーングリップに、ローガリス・マニュスクリプトを渡して下さい。" },
    { id = "quest:97405:completion", html = false,
      ja = "終わったのか？ふう、そうだといいんだが。オーガを怒らせすぎたら、奴らがはるばるここまで押しかけてきて、あいつのちっぽけなレース用カートをばらばらに引き裂くってことを、Gnazはわかってないと思うんだ！\n\nありがとう、これでほっと一息つけるよ。\n\n＜Knazは、本当にほっと一息つく。＞",
      out = "終わったのか？ふう、そうだといいんだが。オーガを怒らせすぎたら、奴らがはるばるここまで押しかけてきて、あいつのちっぽけなレース用カートをばらばらに引き裂くってことを、ナズはわかってないと思うんだ！\n\nありがとう、これでほっと一息つけるよ。\n\n＜ナズは、本当にほっと一息つく。＞" },
    { id = "quest:97919:objectives", html = false,
      ja = "スキルの熟練を示したら、GoldshireのMichelle Belleと話して、あなたの職業用のキャンプ用品の作り方を教わってください。",
      out = "スキルの熟練を示したら、ゴールドシャイアのミシェル・ベルと話して、あなたの職業用のキャンプ用品の作り方を教わってください。" },
    { id = "quest:97964:description", html = false,
      ja = "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nSharpening Wheelの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。",
      out = "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nシャープニング・ホイールの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。" },
    { id = "quest:98203:description", html = false,
      ja = "Witherbarkの奴らは、俺たちが裏切り者として奴らを狩ってるのを知ってる。奴らの欺きのせいで俺たちが焼き払った後でさえ、部族を影に潜ませておくために計画を練り、隠れ家を作ってやがる。\n\n俺たちの斥候が、Hiri'wathaの西に洞窟を見つけた。呪術医のTi'ikって奴が、そこにブードゥーを持ち込んでる……腐敗、朽ち果て、うごめく幼虫、何か汚らわしい魔法のためにな。\n\n俺たちが寝てる間に、あんな汚物を家の中まで這わせるわけにはいかねえ。行け、奴の首を取って、奴らが育ててる物を何であれ叩き潰せ。\n\n奴は手強い。甘く見るんじゃねえぞ、いいな？",
      out = "ウィザーバークの奴らは、俺たちが裏切り者として奴らを狩ってるのを知ってる。奴らの欺きのせいで俺たちが焼き払った後でさえ、部族を影に潜ませておくために計画を練り、隠れ家を作ってやがる。\n\n俺たちの斥候が、ヒリワサの西に洞窟を見つけた。呪術医のティイクって奴が、そこにブードゥーを持ち込んでる……腐敗、朽ち果て、うごめく幼虫、何か汚らわしい魔法のためにな。\n\n俺たちが寝てる間に、あんな汚物を家の中まで這わせるわけにはいかねえ。行け、奴の首を取って、奴らが育ててる物を何であれ叩き潰せ。\n\n奴は手強い。甘く見るんじゃねえぞ、いいな？" },
    { id = "quest:98389:description", html = false,
      ja = "ごきげんよう、{class}。そうだ、私はパラディンだ。死でさえ光を止めることはできない。\n\nこれは我が同類がすべてのForsakenと共有するものだ。我々は、生者が終わりと見なすものを乗り越えてきた。だが、我々の同胞の中にすら我々を恐れる者がいる。我々が彼らを何かの怪物のように打ち倒すのではないかと疑っているのだ。\n\n実のところ、我々とアンデッドであることの関係は複雑だが、私は同胞を傷つけるためにここにいるのではない。そのことを皆に示す手伝いをしてくれ。北西のNight's Web Hollowへ向かい、そこでクモに捕らわれている、蘇ったばかりの愚か者たちを解放してくれ。",
      out = "ごきげんよう、{class}。そうだ、私はパラディンだ。死でさえ光を止めることはできない。\n\nこれは我が同類がすべてのフォーセイクンと共有するものだ。我々は、生者が終わりと見なすものを乗り越えてきた。だが、我々の同胞の中にすら我々を恐れる者がいる。我々が彼らを何かの怪物のように打ち倒すのではないかと疑っているのだ。\n\n実のところ、我々とアンデッドであることの関係は複雑だが、私は同胞を傷つけるためにここにいるのではない。そのことを皆に示す手伝いをしてくれ。北西のナイツ・ウェブ・ホロウへ向かい、そこでクモに捕らわれている、蘇ったばかりの愚か者たちを解放してくれ。" },
    { id = "quest:98830:description", html = false,
      ja = "Prince Tortheldrinの亡骸を調べようと身をかがめると、空気が鋭く金属的な匂いを帯びている。ここで、きわめて強力な魔法が解かれたばかりなのだ。\n\n目の前の亡骸は年老いて風化しており、倒れる前に王子が放っていた生気が失われていることに気づく。他にも身体的な違いがある。\n\nTortheldrinのグレイブの一本が、二つに折れて遺体の近くに転がっている。Shen'dralar Ancientsは、あなたがここで目にしたことを知りたがるだろう。",
      out = "プリンス・トーセルドリンの亡骸を調べようと身をかがめると、空気が鋭く金属的な匂いを帯びている。ここで、きわめて強力な魔法が解かれたばかりなのだ。\n\n目の前の亡骸は年老いて風化しており、倒れる前に王子が放っていた生気が失われていることに気づく。他にも身体的な違いがある。\n\nトーセルドリンのグレイブの一本が、二つに折れて遺体の近くに転がっている。シェンドララー・エンシェントは、あなたがここで目にしたことを知りたがるだろう。" },
    { id = "quest:99144:description", html = false,
      ja = "見つけてくださって、光の祝福を。Bandarion KeepからBrillのShari Stilwellへ伝言を届けに行く途中で、この化け物どもに捕まってしまったのです。奴らは心に憎しみを抱いて光を振るう。そのせいで、私に残ったわずかな血さえも煮えたぎるのです。私が瞑想して求めるすべて……守ろうと努めるすべてに反することです！\n\n<Bareth Dawnstoneは気を落ち着ける。>\n\n私のような者をいまだに快く思わない者がいるのは知っていますが、私たちの意図は純粋だと断言します。ここから逃げるのを手伝ってくだされば、永遠に感謝いたします。",
      out = "見つけてくださって、光の祝福を。バンダリオン・キープからブリルのシャリ・スティルウェルへ伝言を届けに行く途中で、この化け物どもに捕まってしまったのです。奴らは心に憎しみを抱いて光を振るう。そのせいで、私に残ったわずかな血さえも煮えたぎるのです。私が瞑想して求めるすべて……守ろうと努めるすべてに反することです！\n\n<バレス・ドーンストーンは気を落ち着ける。>\n\n私のような者をいまだに快く思わない者がいるのは知っていますが、私たちの意図は純粋だと断言します。ここから逃げるのを手伝ってくだされば、永遠に感謝いたします。" },
    { id = "spell:10160:description", html = false,
      ja = "術者の前方の円錐範囲にいる対象は$N1のFrostダメージを受け、$D1の間、移動速度が$N2%低下します。この円錐で最初に命中した$N4体の対象は、さらに$N5%減速し、その時間が$D2延長されます。",
      out = "術者の前方の円錐範囲にいる対象は$N1のフロストダメージを受け、$D1の間、移動速度が$N2%低下します。この円錐で最初に命中した$N4体の対象は、さらに$N5%減速し、その時間が$D2延長されます。" },
    { id = "spell:1062:aura", html = false,
      ja = "その場から動けません。$N2秒ごとに$N1のNatureダメージを受けます。",
      out = "その場から動けません。$N2秒ごとに$N1のネイチャーダメージを受けます。" },
    { id = "spell:11209:description", html = false,
      ja = "Hammer of Expertiseを召喚します。",
      out = "ハンマー・オブ・エキスパーティーズを召喚します。" },
    { id = "spell:11717:description", html = false,
      ja = "対象に無謀の呪いをかけ、$D1の間、対象のアーマーを$N1減少させます。呪われた敵は逃走せず、FearとHorrorの効果を無視します。1体の対象に対して、各ウォーロックがかけられるCurseは1つだけです。",
      out = "対象に無謀の呪いをかけ、$D1の間、対象のアーマーを$N1減少させます。呪われた敵は逃走せず、フィアーとホラーの効果を無視します。1体の対象に対して、各ウォーロックがかけられるカースは1つだけです。" },
    { id = "spell:1213390:description", html = false,
      ja = "装備しているTimeworn防具の部位ごとに、近接攻撃または遠隔攻撃の命中時に追加攻撃を得る確率が$N1%上昇します。",
      out = "装備しているタイムウォーン防具の部位ごとに、近接攻撃または遠隔攻撃の命中時に追加攻撃を得る確率が$N1%上昇します。" },
    { id = "spell:1215740:description", html = false,
      ja = "敵にShadowダメージを与え、$D1の間、移動速度を低下させます。",
      out = "敵にシャドウダメージを与え、$D1の間、移動速度を低下させます。" },
    { id = "spell:1219250:description", html = false,
      ja = "Mind Flay、Mind Blast、Mind Spikeがアンデッドの対象に与えるダメージが、それぞれのクリティカル率と同じ割合だけ増加します。",
      out = "マインド・フレイ、マインド・ブラスト、マインド・スパイクがアンデッドの対象に与えるダメージが、それぞれのクリティカル率と同じ割合だけ増加します。" },
    { id = "spell:1219838:description", html = false,
      ja = "肩にSoul of the Zealotを永続的に宿らせます：\r\n\nSpirit Tapが有効な間、与えるShadowダメージが$N1%増加します。",
      out = "肩にソウル・オブ・ザ・ゼラットを永続的に宿らせます：\r\n\nスピリット・タップが有効な間、与えるシャドウダメージが$N1%増加します。" },
    { id = "spell:1220022:description", html = false,
      ja = "Rolling with the Punchesが、コンボポイントを得るたびにも発動するようになります。",
      out = "ローリング・ウィズ・ザ・パンチが、コンボポイントを得るたびにも発動するようになります。" },
    { id = "spell:1220340:description", html = false,
      ja = "Tiger's Furyが有効な間、クリティカル率が$N1%上昇します。",
      out = "タイガーズ・フューリーが有効な間、クリティカル率が$N1%上昇します。" },
    { id = "spell:1223385:description", html = false,
      ja = "Naxxramasの中にいる間、あなたの潜在能力を解放します。装備しているSanctifiedアイテム一つにつき、回復量が$N1%、体力が$N2%増加します。（Sanctifiedアイテムを$N3個より多く装備しても、それ以上の効果はありません）",
      out = "ナクスラーマスの中にいる間、あなたの潜在能力を解放します。装備しているサンクティファイドアイテム一つにつき、回復量が$N1%、体力が$N2%増加します。（サンクティファイドアイテムを$N3個より多く装備しても、それ以上の効果はありません）" },
    { id = "spell:1227093:description", html = false,
      ja = "Earth Shieldによる回復に$N1%の確率で、次の詠唱時間のある回復呪文を即時詠唱にする効果が付きます。",
      out = "アース・シールドによる回復に$N1%の確率で、次の詠唱時間のある回復呪文を即時詠唱にする効果が付きます。" },
    { id = "spell:1231227:aura", html = false,
      ja = "Herodが近くにいます。受けるダメージが$N1%減少します。",
      out = "ヘロッドが近くにいます。受けるダメージが$N1%減少します。" },
    { id = "spell:1232096:description", html = false,
      ja = "攻撃呪文のGlobal Cooldownが$N1秒短縮されます。",
      out = "攻撃呪文のグローバル・クールダウンが$N1秒短縮されます。" },
    { id = "spell:1236162:description", html = false,
      ja = "対象を聖なる炎で包み、$N1のHolyダメージを与え、さらに$D2の間、$D1ごとに$N2のHolyダメージを与えます。",
      out = "対象を聖なる炎で包み、$N1のホーリーダメージを与え、さらに$D2の間、$D1ごとに$N2のホーリーダメージを与えます。" },
    { id = "spell:1243072:description", html = false,
      ja = "現在の敵の対象に$N1のShadowダメージを与えます。",
      out = "現在の敵の対象に$N1のシャドウダメージを与えます。" },
    { id = "spell:1249508:description", html = false,
      ja = "$D1かけて体力を$N1回復します。食事中は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間、Fishing Skillが$N4上昇します。$?pc142418[さらに、敵を倒して得る経験値が$N6%増加します。][]",
      out = "$D1かけて体力を$N1回復します。食事中は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間、フィッシング・スキルが$N4上昇します。$?pc142418[さらに、敵を倒して得る経験値が$N6%増加します。][]" },
    { id = "spell:12543:description", html = false,
      ja = "半径3ヤードの対象に$N1のFireダメージを与え、$D1スタンさせます。ダメージを受けると効果は解けます。",
      out = "半径3ヤードの対象に$N1のファイアダメージを与え、$D1スタンさせます。ダメージを受けると効果は解けます。" },
    { id = "spell:1264486:description", html = false,
      ja = "鋭い金切り声を放ち、$N1のNatureダメージを与え、ターゲットを$D1の間スタンさせます。",
      out = "鋭い金切り声を放ち、$N1のネイチャーダメージを与え、ターゲットを$D1の間スタンさせます。" },
    { id = "spell:1269934:description", html = false,
      ja = "遭遇の残りの間、Convoke the Spirits、Assimilation、Dreamfallの効果を即座に発動させます。",
      out = "遭遇の残りの間、コンヴォーク・ザ・スピリット、アシミレーション、ドリームフォールの効果を即座に発動させます。" },
    { id = "spell:1277331:description", html = false,
      ja = "対象を懲らしめ、$N1のHolyダメージを与え、最大$D1の間移動不能にします。Humanoidsにのみ有効です。この呪文が生み出す脅威は非常に低いです。",
      out = "対象を懲らしめ、$N1のホーリーダメージを与え、最大$D1の間移動不能にします。ヒューマノイドにのみ有効です。この呪文が生み出す脅威は非常に低いです。" },
    { id = "spell:1286850:aura", html = false,
      ja = "Darkspear Sharkに噛まれました！$D1ごとに体力の$N1%に相当するダメージを受けています。",
      out = "ダークスピア・シャークに噛まれました！$D1ごとに体力の$N1%に相当するダメージを受けています。" },
    { id = "spell:1291083:description", html = false,
      ja = "Swift Judgementタレントのクールダウンを$N1秒短縮します。",
      out = "スウィフト・ジャッジメントタレントのクールダウンを$N1秒短縮します。" },
    { id = "spell:1293790:description", html = false,
      ja = "敵に冷気の矢を放ち、$N1のFrostダメージを与え、$D1の間移動速度を$N2%下げます。",
      out = "敵に冷気の矢を放ち、$N1のフロストダメージを与え、$D1の間移動速度を$N2%下げます。" },
    { id = "spell:1296330:aura", html = false,
      ja = "あなたは今Emerald Nightmareの中にいます",
      out = "あなたは今エメラルド・ナイトメアの中にいます" },
    { id = "spell:1301051:description", html = false,
      ja = "効果をもたらすAirとEarthのトーテムの効果範囲を$N1ヤード広げます。",
      out = "効果をもたらすエアとアースのトーテムの効果範囲を$N1ヤード広げます。" },
    { id = "spell:1303013:description", html = false,
      ja = "Polearmsのスキルは$N1/$N2です。\n\nレベル$N3の対象：\n命中、回避、受け流し：$N4%\nクリティカルヒット：$N5%\nかすり攻撃のペナルティ：$N6%\nかすり攻撃の確率：$N7%\n$?expandkey[\nレベル$N8の対象：\n命中、回避、受け流し：$N9%\nクリティカルヒット：$N10%\nかすり攻撃のペナルティ：$N11%\nかすり攻撃の確率：$N12%\n\nレベル$N13の対象：\n命中、回避、受け流し：$N14%\nクリティカルヒット：$N15%\nかすり攻撃のペナルティ：$N16%\nかすり攻撃の確率：$N17%\n\nレベル$N18の対象：\n命中、回避、受け流し：$N19%\nクリティカルヒット：$N20%\nかすり攻撃のペナルティ：$N21%\nかすり攻撃の確率：$N22%\n\n|cff9d9d9d最大値を超える武器スキルはかすり攻撃の確率に影響しません。|r\n][]",
      out = "ポールアームのスキルは$N1/$N2です。\n\nレベル$N3の対象：\n命中、回避、受け流し：$N4%\nクリティカルヒット：$N5%\nかすり攻撃のペナルティ：$N6%\nかすり攻撃の確率：$N7%\n$?expandkey[\nレベル$N8の対象：\n命中、回避、受け流し：$N9%\nクリティカルヒット：$N10%\nかすり攻撃のペナルティ：$N11%\nかすり攻撃の確率：$N12%\n\nレベル$N13の対象：\n命中、回避、受け流し：$N14%\nクリティカルヒット：$N15%\nかすり攻撃のペナルティ：$N16%\nかすり攻撃の確率：$N17%\n\nレベル$N18の対象：\n命中、回避、受け流し：$N19%\nクリティカルヒット：$N20%\nかすり攻撃のペナルティ：$N21%\nかすり攻撃の確率：$N22%\n\n|cff9d9d9d最大値を超える武器スキルはかすり攻撃の確率に影響しません。|r\n][]" },
    { id = "spell:1307264:description", html = false,
      ja = "必要とするレシピに使えるMolten Foundryを設置し、Lodestoneの効果もすべて得られます。近くにCampfireが必要です。\n\nLodestoneの上に設置すると置き換えられます。すべての野営設備はクールダウン$D1を共有します。",
      out = "必要とするレシピに使えるモルテン・ファウンドリーを設置し、ロードストーンの効果もすべて得られます。近くにキャンプファイアが必要です。\n\nロードストーンの上に設置すると置き換えられます。すべての野営設備はクールダウン$D1を共有します。" },
    { id = "spell:1310015:description", html = false,
      ja = "Stranglethorn ValeとRivergladesで移動速度が$N1%上昇します。",
      out = "ストラングルソーン・ヴェイルとリヴァーグレイズで移動速度が$N1%上昇します。" },
    { id = "spell:1315190:description", html = false,
      ja = "短い間、戦闘で自分を守るBlack Dragon Whelpを呼び出します。",
      out = "短い間、戦闘で自分を守るブラック・ドラゴン・ウェルプを呼び出します。" },
    { id = "spell:1319257:description", html = false,
      ja = "武器を清め、次の攻撃で$N1の追加ダメージを与えます。与えるダメージはすべてHolyの魔法によるものです。",
      out = "武器を清め、次の攻撃で$N1の追加ダメージを与えます。与えるダメージはすべてホーリーの魔法によるものです。" },
    { id = "spell:1325764:description", html = false,
      ja = "あなたはまだDalaranの街に入ることを許されていません。",
      out = "あなたはまだダラランの街に入ることを許されていません。" },
    { id = "spell:13485:description", html = false,
      ja = "shieldに精神を3上昇させる永続的な\n魔力付与を行います。",
      out = "シールドに精神を3上昇させる永続的な\n魔力付与を行います。" },
    { id = "spell:13967:description", html = false,
      ja = "Fist Weaponsでのクリティカル率を$N1%上昇させます。",
      out = "フィスト・ウェポンでのクリティカル率を$N1%上昇させます。" },
    { id = "spell:14542:description", html = false,
      ja = "Frost Resistanceが$N1上昇します。",
      out = "フロスト・レジスタンスが$N1上昇します。" },
    { id = "spell:14684:description", html = false,
      ja = "Shadow Resistanceが$N1上昇します。",
      out = "シャドウ・レジスタンスが$N1上昇します。" },
    { id = "spell:15062:description", html = false,
      ja = "$D1の間、術者が受けるPhysicalダメージと魔法のダメージを$N1%軽減します。",
      out = "$D1の間、術者が受けるフィジカルダメージと魔法のダメージを$N1%軽減します。" },
    { id = "spell:15619:description", html = false,
      ja = "敵にレンチを投げつけ、Physicalダメージを与えます。",
      out = "敵にレンチを投げつけ、フィジカルダメージを与えます。" },
    { id = "spell:15913:description", html = false,
      ja = "Two-handed Axesが+$N1上昇します。",
      out = "ツー・ハンデッド・アックスが+$N1上昇します。" },
    { id = "spell:16400:description", html = false,
      ja = "対象を毒に侵し、$D2の間、$N2秒ごとに$N1のNatureダメージを与えます。",
      out = "対象を毒に侵し、$D2の間、$N2秒ごとに$N1のネイチャーダメージを与えます。" },
    { id = "spell:16914:description", html = false,
      ja = "対象の範囲に激しい嵐を起こし、$N2秒ごとに敵に$N1のNatureダメージを与え、敵の攻撃間隔を$N3%長くします。$D2持続します。ドルイドは呪文を維持するためにチャネリングし続ける必要があります。",
      out = "対象の範囲に激しい嵐を起こし、$N2秒ごとに敵に$N1のネイチャーダメージを与え、敵の攻撃間隔を$N3%長くします。$D2持続します。ドルイドは呪文を維持するためにチャネリングし続ける必要があります。" },
    { id = "spell:17332:description", html = false,
      ja = "Chance on Hit：$D1の間、対象を動けなくし、アーマーを$N1下げます。",
      out = "チャンス・オン・ヒット：$D1の間、対象を動けなくし、アーマーを$N1下げます。" },
    { id = "spell:17837:description", html = false,
      ja = "Arcaneの呪文と効果によるダメージを最大$N1増加させます。",
      out = "アーケインの呪文と効果によるダメージを最大$N1増加させます。" },
    { id = "spell:18074:description", html = false,
      ja = "アンデッドに対するAttack Powerが$N1上昇します。",
      out = "アンデッドに対するアタック・パワーが$N1上昇します。" },
    { id = "spell:18647:description", html = false,
      ja = "敵の対象を追放し、最大$D1の間あらゆる行動を封じますが、無敵状態にします。同時に追放できる対象は1体だけです。悪魔とElementalsにのみ有効です。",
      out = "敵の対象を追放し、最大$D1の間あらゆる行動を封じますが、無敵状態にします。同時に追放できる対象は1体だけです。悪魔とエレメンタルにのみ有効です。" },
    { id = "spell:19273:description", html = false,
      ja = "プリーストが反魔法のエネルギーに包まれます。プリーストに対して呪文が成功するたびに、攻撃者のマナを$N1焼却し、焼却したマナのポイントごとに$N2のShadowダメージを与えます。効果時間は$D1です。",
      out = "プリーストが反魔法のエネルギーに包まれます。プリーストに対して呪文が成功するたびに、攻撃者のマナを$N1焼却し、焼却したマナのポイントごとに$N2のシャドウダメージを与えます。効果時間は$D1です。" },
    { id = "spell:19696:description", html = false,
      ja = "Surf Crawlerの手なずけを開始し、$N1分間仲間にします。何らかの理由で獣の注意がそれると、手なずけは失敗します。",
      out = "サーフ・クローラーの手なずけを開始し、$N1分間仲間にします。何らかの理由で獣の注意がそれると、手なずけは失敗します。" },
    { id = "spell:20091:description", html = false,
      ja = "Retribution Auraで与えるダメージを$N1%増加させます。",
      out = "レトリビューション・オーラで与えるダメージを$N1%増加させます。" },
    { id = "spell:20411:description", html = false,
      ja = "対象を裁き、Holyダメージを与えます。",
      out = "対象を裁き、ホーリーダメージを与えます。" },
    { id = "spell:20806:description", html = false,
      ja = "敵にFrostダメージを与え、$D1の間、移動速度を低下させます。",
      out = "敵にフロストダメージを与え、$D1の間、移動速度を低下させます。" },
    { id = "spell:21335:description", html = false,
      ja = "味方の対象から棘が生え、攻撃してきた相手に$N1のNatureダメージを与えます。効果時間は$D1です。",
      out = "味方の対象から棘が生え、攻撃してきた相手に$N1のネイチャーダメージを与えます。効果時間は$D1です。" },
    { id = "spell:21787:description", html = false,
      ja = "$D2の間、$D1ごとに敵に$N1のNatureダメージを与えます。",
      out = "$D2の間、$D1ごとに敵に$N1のネイチャーダメージを与えます。" },
    { id = "spell:22696:aura", html = false,
      ja = "攻撃者に$N1のNatureダメージを与えます。",
      out = "攻撃者に$N1のネイチャーダメージを与えます。" },
    { id = "spell:23152:description", html = false,
      ja = "力を帯びたCircle of Dark Summoningの中でXorothian Dreadsteedを召喚します。",
      out = "力を帯びたサークル・オブ・ダーク・サモニングの中でゾロシアン・ドレッドスティードを召喚します。" },
    { id = "spell:23573:description", html = false,
      ja = "Healing Waveが近くの別の対象へ跳ねるようになります。跳ねるたびに回復効果が80%低下し、最大2体の追加の対象へ跳ねます。",
      out = "ヒーリング・ウェーブが近くの別の対象へ跳ねるようになります。跳ねるたびに回復効果が80%低下し、最大2体の追加の対象へ跳ねます。" },
    { id = "spell:24374:description", html = false,
      ja = "敵にFireダメージを与えます。",
      out = "敵にファイアダメージを与えます。" },
    { id = "spell:24589:description", html = false,
      ja = "$D1かけて$N1のNatureダメージを与えます。この効果は1体の対象に最大$N3回まで重ねられます。",
      out = "$D1かけて$N1のネイチャーダメージを与えます。この効果は1体の対象に最大$N3回まで重ねられます。" },
    { id = "spell:25025:description", html = false,
      ja = "衝撃の力で敵を打ち、Natureダメージを与え、$D1の間、詠唱中の呪文を妨害します。",
      out = "衝撃の力で敵を打ち、ネイチャーダメージを与え、$D1の間、詠唱中の呪文を妨害します。" },
    { id = "spell:25953:description", html = false,
      ja = "高周波音を発し、Temple of \nAhn'Qirajの下にある巣穴からシリシッド・\nタンクを出てこさせます。出てきた\nシリシッドは召喚者に従順で、Temple \nof Ahn'Qiraj内で乗り物として使えます。\n乗り手が攻撃を受けるとシリシッド・\nタンクは地下へ追い返されます。",
      out = "高周波音を発し、テンプル・オブ \nアンキラージの下にある巣穴からシリシッド・\nタンクを出てこさせます。出てきた\nシリシッドは召喚者に従順で、テンプル \nオブ・アンキラージ内で乗り物として使えます。\n乗り手が攻撃を受けるとシリシッド・\nタンクは地下へ追い返されます。" },
    { id = "spell:26468:description", html = false,
      ja = "Right Clickで雪だるまを呼び出したり帰したりします。",
      out = "ライト・クリックで雪だるまを呼び出したり帰したりします。" },
    { id = "spell:27620:aura", html = false,
      ja = "Silenced",
      out = "サイレンスト" },
    { id = "spell:28310:description", html = false,
      ja = "敵にShadowダメージを与え、$D1の間、移動速度を低下させます。",
      out = "敵にシャドウダメージを与え、$D1の間、移動速度を低下させます。" },
    { id = "spell:28870:description", html = false,
      ja = "アンデッドに対するAttack Powerが$N1上昇します。",
      out = "アンデッドに対するアタック・パワーが$N1上昇します。" },
    { id = "spell:30801:description", html = false,
      ja = "戦闘中でも、$N2秒ごとにSTAの$N1%に等しい体力を回復します。",
      out = "戦闘中でも、$N2秒ごとにスタミナの$N1%に等しい体力を回復します。" },
    { id = "spell:364455:aura", html = false,
      ja = "|cFFffd200Bonus Event: Season of Mastery|r\r\n\n体力が$N1%増加します。",
      out = "|cFFffd200ボーナス・イベント: シーズン・オブ・マスタリー|r\r\n\n体力が$N1%増加します。" },
    { id = "spell:400039:description", html = false,
      ja = "Just a Flesh Woundのアビリティを得ます：\n\n$I1\nBlade Danceが有効な間、受けるPhysicalダメージが$N1%減少し、Defenseスキルが$N4を超える$N3ごとにさらに1%減少します。さらに、Dodgeの確率が$N5%倍になり、近接攻撃でクリティカルヒットを受ける確率が$N6%減少し、与えるダメージが$N7%減少し、すべての行動で発生する脅威が大幅に増加し、FeintのアビリティがTeaseに置き換わります。Teaseは対象をTauntして自分を攻撃させます。\n\n$I2\n対象をTauntして自分を攻撃させますが、対象がすでに自分を攻撃している場合は効果がありません。",
      out = "ジャスト・ア・フレッシュ・ウーンドのアビリティを得ます：\n\n$I1\nブレード・ダンスが有効な間、受けるフィジカルダメージが$N1%減少し、ディフェンススキルが$N4を超える$N3ごとにさらに1%減少します。さらに、ドッジの確率が$N5%倍になり、近接攻撃でクリティカルヒットを受ける確率が$N6%減少し、与えるダメージが$N7%減少し、すべての行動で発生する脅威が大幅に増加し、フェイントのアビリティがティーズに置き換わります。ティーズは対象をトーントして自分を攻撃させます。\n\n$I2\n対象をトーントして自分を攻撃させますが、対象がすでに自分を攻撃している場合は効果がありません。" },
    { id = "spell:402922:description", html = false,
      ja = "Slamが即時になりますが、$D1のクールダウンが付きます。",
      out = "スラムが即時になりますが、$D1のクールダウンが付きます。" },
    { id = "spell:408477:description", html = false,
      ja = "対象に雷の矢を放ち、$N1のNatureダメージを与えます。",
      out = "対象に雷の矢を放ち、$N1のネイチャーダメージを与えます。" },
    { id = "spell:411995:description", html = false,
      ja = "$D1ごとに$N1のShadowダメージを与えます。",
      out = "$D1ごとに$N1のシャドウダメージを与えます。" },
    { id = "spell:415709:description", html = false,
      ja = "Survival of the Fittestのアビリティを得ます：\n\n$I1\n近接攻撃でクリティカルヒットを受ける確率が$N1%減少し、受けるすべてのダメージが$N2%減少します。Bear FormまたはDire Bear Formの間は、受けるダメージがさらに$N3%減少します。",
      out = "サバイバル・オブ・ザ・フィッテストのアビリティを得ます：\n\n$I1\n近接攻撃でクリティカルヒットを受ける確率が$N1%減少し、受けるすべてのダメージが$N2%減少します。ベア・フォームまたはダイア・ベア・フォームの間は、受けるダメージがさらに$N3%減少します。" },
    { id = "spell:423300:description", html = false,
      ja = "M'grrglが$D1の間同行し、闇からわずかに守ってくれます。",
      out = "ムグルグルが$D1の間同行し、闇からわずかに守ってくれます。" },
    { id = "spell:426174:description", html = false,
      ja = "Malleable Protectionのアビリティを得ます：\n\n$I1\nDivine Protectionの間も行動できるようになり、効果時間が$N1%延長されますが、無敵になる代わりに受けるダメージを$N2%減少させるだけになります。さらに、Holy Shieldを使用すると、防御スキルが$N4を超えるポイントごとにAttack Powerを$N3得て、$D1持続します。",
      out = "マリアブル・プロテクションのアビリティを得ます：\n\n$I1\nディバイン・プロテクションの間も行動できるようになり、効果時間が$N1%延長されますが、無敵になる代わりに受けるダメージを$N2%減少させるだけになります。さらに、ホーリー・シールドを使用すると、防御スキルが$N4を超えるポイントごとにアタック・パワーを$N3得て、$D1持続します。" },
    { id = "spell:429261:description", html = false,
      ja = "手首にHammer of Wrathのルーンを刻みます：\n\n$I1\nHammer of Wrathが即時詠唱になり、体力が$N1%未満の敵にダメージを与えるたびにHammer of Wrathのクールダウンがリセットされます。",
      out = "手首にハンマー・オブ・ラスのルーンを刻みます：\n\n$I1\nハンマー・オブ・ラスが即時詠唱になり、体力が$N1%未満の敵にダメージを与えるたびにハンマー・オブ・ラスのクールダウンがリセットされます。" },
    { id = "spell:432149:description", html = false,
      ja = "対象に稲妻を放ち、$N1のNatureダメージを与えます。",
      out = "対象に稲妻を放ち、$N1のネイチャーダメージを与えます。" },
    { id = "spell:435935:description", html = false,
      ja = "Guardian Glovesを$N1個追加して、出荷を完了させます。",
      out = "ガーディアン・グローブを$N1個追加して、出荷を完了させます。" },
    { id = "spell:4374:description", html = false,
      ja = "One-Handed Macesでのダメージが$N1増加します。",
      out = "ワン・ハンデッド・メイスでのダメージが$N1増加します。" },
    { id = "spell:440505:aura", html = false,
      ja = "Invisibility",
      out = "インビジビリティー" },
    { id = "spell:444895:description", html = false,
      ja = "敵を打ち据え、Holyダメージを与えます。",
      out = "敵を打ち据え、ホーリーダメージを与えます。" },
    { id = "spell:447255:description", html = false,
      ja = "Dragonkinに対するAttack Powerが$N1上昇します。",
      out = "ドラゴンキンに対するアタック・パワーが$N1上昇します。" },
    { id = "spell:4541:description", html = false,
      ja = "Holy耐性が$N1増加します。",
      out = "ホーリー耐性が$N1増加します。" },
    { id = "spell:459584:description", html = false,
      ja = "Wing Clipの持続時間が$D1長くなります。",
      out = "ウィング・クリップの持続時間が$D1長くなります。" },
    { id = "spell:461301:description", html = false,
      ja = "Healing Rain呪文の詠唱時間が$N1%短縮されます。",
      out = "ヒーリング・レイン呪文の詠唱時間が$N1%短縮されます。" },
    { id = "spell:463555:description", html = false,
      ja = "Blood Godへの奉仕に対する証を受け取ります。",
      out = "ブラッド・ゴッドへの奉仕に対する証を受け取ります。" },
    { id = "spell:467529:description", html = false,
      ja = "Judgementを使うと、$D1の間、与えるHolyダメージが$N1%増加します。最大$N3回まで重なります。",
      out = "ジャッジメントを使うと、$D1の間、与えるホーリーダメージが$N1%増加します。最大$N3回まで重なります。" },
    { id = "spell:468670:description", html = false,
